// Single source of truth for the developer-resource index. Rendered as HTML by
// app/(home)/developers/page.tsx and as Markdown by app/api/page-md, so the
// human page and the agent-readable twin can never disagree about what exists.
//
// Why the Markdown twin exists: the Is Agentic audit failed "developer resource
// discoverability" ("searched for \"yonyon\" developer resources but found
// nothing relevant"). The page was already served and in the sitemap, but an
// agent following our own documented convention (append `.md` to a page URL)
// got an HTML 404 for /developers.md. Predictable URL, machine-readable body.

import { COUNTS } from "@/lib/constants";

// The resource types orank's "Developer resource discoverability" check
// recognizes (methodology, 2026-09-27: "API docs, OpenAPI specs, MCP server,
// auth docs, developer portal, SDK documentation"), plus the plugin's own
// install guide and reference, which are what a developer searches for first.
export type DeveloperResourceKind =
	| "API docs"
	| "OpenAPI spec"
	| "MCP server"
	| "SDK documentation"
	| "Auth docs"
	| "Install guide"
	| "Reference docs";

export type DeveloperResource = {
	title: string;
	desc: string;
	href: string;
	external?: boolean;
	/** Set on the named, product-titled landing pages. These feed the
	 * "Developer resources" section of /llms.txt and /llms-full.txt. */
	kind?: DeveloperResourceKind;
};

